import 'package:flutter/material.dart';
import 'nutri_world.dart';
class NutriWorldScreen extends StatefulWidget { const NutriWorldScreen({super.key,required this.repository}); final NutriWorldRepository repository; @override State<NutriWorldScreen> createState()=>_NutriWorldScreenState(); }
class _NutriWorldScreenState extends State<NutriWorldScreen>{late NutriWorldState state; @override void initState(){super.initState();state=widget.repository.load();} @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Meine NutriWorld')),body:GridView.count(crossAxisCount:2,padding:const EdgeInsets.all(16),crossAxisSpacing:12,mainAxisSpacing:12,children:[_card(c,'Garten',state.garden,Icons.local_florist,Colors.green),_card(c,'Baum',state.tree,Icons.park,Colors.teal),_card(c,'Weg',state.path,Icons.directions_walk,Colors.orange),_card(c,'Teich',state.pond,Icons.water,Colors.blue),_card(c,'Küche',state.kitchen,Icons.restaurant,Colors.redAccent),_card(c,'Vorrat',state.pantry,Icons.inventory_2,Colors.purple)])); Widget _card(BuildContext c,String title,int points,IconData icon,Color color)=>TweenAnimationBuilder<double>(tween:Tween(begin:0,end:1),duration:const Duration(milliseconds:650),curve:Curves.easeOutCubic,builder:(_,v,child)=>Transform.scale(scale:.94+.06*v,child:Opacity(opacity:v,child:child)),child:Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(icon,size:42,color:color),const Spacer(),Text(title,style:Theme.of(c).textTheme.titleLarge),Text('$points Wachstumspunkte'),const SizedBox(height:8),LinearProgressIndicator(value:(points/20).clamp(0,1).toDouble(),color:color,backgroundColor:color.withValues(alpha:.16))]))));}
